Oplossing:
Nim altyd earst de doazen mei it grutste tal lucifers. Sortearje de m typen op bi ôfnimmend. Hâld in oantal reste = n doazen oer; foar elke type nim k = min(ai, reste) doazen en foegje k * bi ta oan it totaal. Brûk 64-bit foar de som (long long) om feilich te wêzen.

Tydskompleksiteit: O(m log m) (m ≤ 20).

C++-implementaasje:
#include <bits/stdc++.h>
using namespace std;
int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n; int m;
    if(!(cin>>n>>m)) return 0;
    vector<pair<long long,long long>> v; // (bi, ai)
    for(int i=0;i<m;++i){
        long long a,b; cin>>a>>b;
        v.emplace_back(b,a);
    }
    sort(v.begin(), v.end(), greater<>());
    long long reste = n;
    long long ans = 0;
    for(auto &p: v){
        if(reste==0) break;
        long long bi = p.first;
        long long ai = p.second;
        long long take = min(ai, reste);
        ans += take * bi;
        reste -= take;
    }
    cout<<ans<<"\n";
    return 0;
}

